public static boolean isTooManyRequest(Throwable ex) {
    while (ex != null) {
      if (ex.getMessage() != null && ex.getMessage().toLowerCase().contains("too many request")) {
        return true;
      }
      ex = ex.getCause();
    }
    return false;
  }

